const LANG=(()=>{const h=window.__MIWIFI_LANG__;if(h)return /^pt/i.test(h)?'pt':'en';
  try{const l=localStorage.getItem('lang');if(l==='pt'||l==='en')return l;}catch(_){}
  return /^pt/i.test(navigator.language||'')?'pt':'en';})();
const _ch=Object.keys(I18N_EN).filter(k=>k[0]!=='_').sort((a,b)=>b.length-a.length);
const _rx=_ch.length?new RegExp('(?<![\\p{L}\\p{N}])(?:'+_ch.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![\\p{L}\\p{N}])','gu'):null;
function tr(t){if(LANG!=='en'||!t||!_rx)return t;const x=t.trim();if(I18N_EN[x]!==undefined)return t.replace(x,I18N_EN[x]);return t.replace(_rx,m=>I18N_EN[m]);}
function traduzir(no){if(LANG!=='en'||!no)return;const w=document.createTreeWalker(no,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);let n=no;
  while(n){if(n.nodeType===3){const pe=n.parentElement;if(pe&&!pe.closest('pre,textarea,script,style,.mono,.notr')&&/[A-Za-zÀ-ú]/.test(n.nodeValue)){const v=tr(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v;}}
    else if(n.nodeType===1){for(const a of ['placeholder','title']){const v=n.getAttribute(a);if(v){const x=tr(v);if(x!==v)n.setAttribute(a,x);}}}
    n=w.nextNode();}}

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const _q=new URLSearchParams(window.__MIWIFI_QUERY__??location.search);
